import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"', doublequote=True)

    # This format has one logical header row, preceded at most by blank lines.
    for record in reader:
        if record:
            columns = [field.strip() for field in record]
            break
    else:
        return {"columns": [], "rows": []}

    rows = list(reader)
    expected_width = 4
    width = max(expected_width, len(columns), max(map(len, rows), default=0))

    # Preserve overflow fields in separate columns rather than dropping them.
    used_names = set(columns)
    for index in range(len(columns), width):
        base = f"column_{index + 1}" if index < expected_width else f"extra_{index + 1 - expected_width}"
        name = base
        suffix = 2
        while name in used_names:
            name = f"{base}_{suffix}"
            suffix += 1
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
